import test from 'node:test';
import assert from 'node:assert';
import { deepClone } from './solution.js';

test('clones primitives', () => {
  assert.strictEqual(deepClone(42), 42);
  assert.strictEqual(deepClone('hi'), 'hi');
  assert.strictEqual(deepClone(null), null);
});

test('clones flat object', () => {
  const obj = { a: 1, b: 'two' };
  const clone = deepClone(obj);
  assert.deepStrictEqual(clone, obj);
  clone.a = 99;
  assert.strictEqual(obj.a, 1);
});

test('clones nested object', () => {
  const obj = { x: { y: { z: 3 } } };
  const clone = deepClone(obj);
  clone.x.y.z = 0;
  assert.strictEqual(obj.x.y.z, 3);
});

test('clones array', () => {
  const arr = [1, [2, 3], { a: 4 }];
  const clone = deepClone(arr);
  clone[1][0] = 99;
  assert.strictEqual(arr[1][0], 2);
});

reference_solution:
export function deepClone(obj) {
  if (obj === null || typeof obj !== "object") return obj;
  if (Array.isArray(obj)) return obj.map(deepClone);
  const out = {};
  for (const [key, value] of Object.entries(obj)) out[key] = deepClone(value);
  return out;
}
